package ro.leo.visual;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.os.*;import android.view.*;import java.io.*;
/** Visual fixture only. Controls cannot start playback or alter system volume in preview. */
public final class MediaDashboardTests extends Instrumentation {
 private int count;private void check(boolean b,String s){if(!b)throw new AssertionError(s);count++;}
 private Object get(Object o,String n)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private void capture(String name)throws Exception{waitForIdleSync();SystemClock.sleep(200);Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"material-"+name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
 public void onCreate(Bundle b){start();}public void onStart(){final Context c=getTargetContext();Bundle result=new Bundle();Activity activity=null;PlaybackService before=PlaybackService.instance;boolean fm=FmService.playing;AudioManager audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);int volume=audio.getStreamVolume(AudioManager.STREAM_MUSIC);try{check(Appearance.THEMES.length==Appearance.COLORS.length&&Appearance.THEMES[9].contains("Material"),"material palette available");check(BackupEngine.allowed("appearance","app-theme-NowPlayingActivity","int"),"media theme accepted by settings backup");activity=startActivitySync(new Intent(c,NowPlayingActivity.class).putExtra("preview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final Activity a=activity;runOnMainSync(new Runnable(){public void run(){try{java.lang.reflect.Field f=a.getClass().getDeclaredField("source");f.setAccessible(true);f.setInt(a,0);((View)a.getWindow().getDecorView()).invalidate();}catch(Exception e){throw new RuntimeException(e);}}});for(int i=0;i<30&&!activity.hasWindowFocus();i++)SystemClock.sleep(100);capture("music");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();check((Boolean)get(activity,"previewPlaying"),"OK toggles dashboard fixture");sendKeyDownUpSync(KeyEvent.KEYCODE_STAR);waitForIdleSync();check((Integer)get(activity,"source")==1,"star changes to radio source");capture("fm");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_UP);waitForIdleSync();check((Integer)get(activity,"previewVolume")==7&&audio.getStreamVolume(AudioManager.STREAM_MUSIC)==volume,"demo volume is isolated");sendKeyDownUpSync(KeyEvent.KEYCODE_6);sendKeyDownUpSync(KeyEvent.KEYCODE_POUND);check(PlaybackService.instance==before&&FmService.playing==fm,"demo controls do not start real media");result.putString("result","PASS "+count+" media dashboard checks; silent visual fixture");}catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(activity!=null){final Activity a=activity;runOnMainSync(new Runnable(){public void run(){a.finish();}});}}finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}
